-- Тема 16: варианты ответов выровнены по длине и форме (48 исправлений в 16 вопросах), ключи не меняются.
-- Источник: scripts/questions/072_option_length_topic16.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Что передаётся подписчику при логической репликации?', 'Тексты SQL-команд', 'Тексты SQL-команд, выполненных на издателе', 'Команды SQL не передаются.', NULL),
        ('option', 'Что передаётся подписчику при логической репликации?', 'Страницы данных', 'Изменённые страницы данных таблиц', 'Физическая репликация передаёт записи WAL, а не страницы.', NULL),
        ('option', 'Что передаётся подписчику при логической репликации?', 'Файлы WAL без изменений', 'Сегменты WAL целиком, без декодирования', 'Файлы WAL передаёт физическая репликация.', NULL),
        ('option', 'Что передаётся подписчику при логической репликации?', 'Изменения строк таблиц, декодированные из WAL', 'Изменения строк, декодированные из WAL', 'Логическое декодирование превращает записи журнала в изменения строк.', 'Логическое декодирование превращает записи журнала в изменения строк таблиц.'),
        ('option', 'Какая совместимость серверов нужна для логической репликации?', 'Только на уровне протокола, двоичная не нужна', 'Совместимость протокола, а не двоичная', 'Двоичная совместимость файлов не нужна, достаточно протокола; при binary = true нужны ещё совместимые двоичные форматы типов.', NULL),
        ('option', 'Какая совместимость серверов нужна для логической репликации?', 'Двоичная', 'Двоичная, как при физической репликации', 'Двоичная совместимость нужна физической репликации.', NULL),
        ('option', 'Какая совместимость серверов нужна для логической репликации?', 'Одна и та же основная версия', 'Одна и та же основная версия PostgreSQL', 'Основные версии могут различаться.', NULL),
        ('option', 'Реплицируются ли команды DDL?', 'Да, все', 'Да, все изменения схемы передаются подписчику', 'DDL не реплицируются.', NULL),
        ('option', 'Реплицируются ли команды DDL?', 'Только CREATE TABLE', 'Частично: создание таблиц передаётся', 'Тоже нет.', 'Нет: команды DDL, включая CREATE TABLE, не реплицируются.'),
        ('option', 'Реплицируются ли команды DDL?', 'Нет, таблицы на подписчике создают вручную', 'Нет, схему на подписчике меняют вручную', 'Изменения схемы переносят вручную.', 'Изменения схемы, в том числе создание таблиц, переносят на подписчик вручную.'),
        ('option', 'Реплицируются ли команды DDL?', 'Только при wal_level = logical', 'Да, если задано wal_level = logical', 'Уровень журнала на это не влияет.', NULL),
        ('option', 'Что из перечисленного не реплицируется логической репликацией?', 'INSERT', 'Вставки строк (INSERT)', 'Реплицируется.', NULL),
        ('option', 'Что из перечисленного не реплицируется логической репликацией?', 'UPDATE', 'Изменения строк (UPDATE)', 'Реплицируется.', NULL),
        ('option', 'Что из перечисленного не реплицируется логической репликацией?', 'TRUNCATE', 'Опустошение таблиц (TRUNCATE)', 'Реплицируется.', NULL),
        ('option', 'Как по умолчанию идентифицируется строка при репликации UPDATE и DELETE?', 'По всем столбцам', 'По всем столбцам строки', 'Только при REPLICA IDENTITY FULL.', NULL),
        ('option', 'Как по умолчанию идентифицируется строка при репликации UPDATE и DELETE?', 'По ctid', 'По физическому адресу ctid', 'ctid — физический адрес, у подписчика он другой.', NULL),
        ('option', 'Как по умолчанию идентифицируется строка при репликации UPDATE и DELETE?', 'По oid строки', 'По системному oid строки', 'У строк пользовательских таблиц нет автоматического oid.', NULL),
        ('option', 'Что происходит при конфликте (нарушении ограничения) на подписчике?', 'Строка пропускается', 'Конфликтующая строка пропускается без ошибки', 'Автоматически строка не пропускается.', NULL),
        ('option', 'Что происходит при конфликте (нарушении ограничения) на подписчике?', 'Побеждает последнее изменение', 'Побеждает изменение с более поздней меткой времени', 'Такого правила нет.', NULL),
        ('option', 'Что происходит при конфликте (нарушении ограничения) на подписчике?', 'Подписка удаляется', 'Подписка удаляется вместе со своим слотом репликации', 'Подписка остаётся.', NULL),
        ('option', 'Что происходит при конфликте (нарушении ограничения) на подписчике?', 'Применение изменений приостанавливается до ручного разрешения конфликта', 'Применение изменений встаёт до ручного решения', 'Конфликт разрешают вручную.', 'Применение изменений приостанавливается, пока конфликт не разрешат вручную.'),
        ('option', 'Какой процесс на подписчике применяет полученные изменения?', 'startup', 'logical replication launcher', 'Применяет журнал на физической реплике.', 'Запускает рабочие процессы подписок, а изменения применяют они.'),
        ('option', 'Чем опасен неактивный слот логической репликации?', 'Блокирует таблицы публикации', 'Блокирует таблицы публикации для записи', 'Таблицы не блокируются.', NULL),
        ('option', 'Чем опасен неактивный слот логической репликации?', 'Отключает автоочистку', 'Отключает автоочистку на издателе', 'Автоочистка работает, но горизонт удерживается.', NULL),
        ('option', 'Чем опасен неактивный слот логической репликации?', 'Удерживает сегменты WAL и горизонт очистки', 'Удерживает журнал и горизонт очистки', 'Сервер копит журнал и удерживает версии строк системного каталога, нужные для декодирования.', 'Сервер копит сегменты WAL и удерживает версии строк системного каталога, нужные для декодирования.'),
        ('option', 'Чем опасен неактивный слот логической репликации?', 'Удаляет публикацию', 'Удаляет публикацию через заданное время', 'Публикация не удаляется.', NULL),
        ('option', 'Что не передаётся логической репликацией?', '`INSERT`', 'Вставки строк (INSERT)', 'Реплицируется.', NULL),
        ('option', 'Что не передаётся логической репликацией?', '`TRUNCATE`', 'Опустошение таблиц (TRUNCATE)', 'Реплицируется.', NULL),
        ('option', 'Чем логическая репликация отличается от физической?', 'Подписчик доступен только для чтения', 'Подписчик доступен для чтения, но не для записи', 'Подписчик — обычный сервер, данные можно изменять.', NULL),
        ('option', 'Чем логическая репликация отличается от физической?', 'Передаются страницы данных', 'Передаются изменённые страницы данных', 'Передаются изменения строк, а не страницы.', NULL),
        ('option', 'Какими способами можно идентифицировать строки при логической репликации UPDATE и DELETE?', 'По ctid', 'По физическому адресу ctid', 'ctid у подписчика другой.', NULL),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Опубликовать только customers', 'Опубликовать customers без таблицы orders', 'На подписчике опустошение customers упрётся во внешний ключ таблицы orders.', NULL),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Удалить внешний ключ на подписчике', 'Удалить внешний ключ на подписчике заранее', 'Нет. Ключ по условию должен сохраниться, а его удаление само по себе не обеспечивает репликацию опустошения orders.', NULL),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Реплицировать orders той же подпиской, что и customers', 'Включить orders в ту же подписку, что customers', 'Да. Все таблицы, которые затронет TRUNCATE CASCADE, должны входить в одну подписку; публикации при этом могут быть разными.', NULL),
        ('option', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть и должен сохраниться. Что нужно, чтобы команда TRUNCATE customers CASCADE правильно реплицировалась для обеих таблиц?', 'Ничего, TRUNCATE не реплицируется', 'Ничего: TRUNCATE не входит в логическую репликацию', 'Публикация обрабатывает и TRUNCATE.', NULL),
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Да, но только при синхронной репликации', 'Да, но при синхронной репликации с издателем', 'Режим синхронности здесь значения не имеет.', NULL),
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Нет, источником всегда служит публикующий сервер', 'Нет, источником служит сам публикующий сервер', 'Допускается и физическая реплика публикующего сервера.', NULL),
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Да, отправку изменений выполняет wal_sender физической реплики', 'Да, изменения отправляет wal_sender физической реплики', 'Это уменьшает нагрузку на публикующий сервер.', NULL),
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Нет, физические реплики не поддерживают протокол репликации', 'Нет, физическая реплика не обслуживает этот протокол', 'Подключения по этому протоколу они обслуживают.', NULL),
        ('option', 'Почему для обновления основной версии без прерывания обслуживания не подходит физическая репликация?', 'Физическая репликация реплицирует только отдельные таблицы', 'Физическая репликация передаёт отдельные таблицы, а не кластер', 'Реплицируется только весь кластер.', NULL),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Да, в PostgreSQL 16 они поддерживаются', 'Да, в PostgreSQL 16 они поддерживаются штатно', 'Распределённых транзакций такая схема не даёт.', NULL),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Да, но только при синхронной фиксации', 'Да, но при синхронной фиксации на всех узлах', 'Синхронная фиксация этого не меняет.', NULL),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Нет, согласованность между серверами сама по себе не обеспечивается', 'Нет, общей согласованности узлов она не даёт', 'Приложение должно избегать конфликтов, а сбои и состав узлов обрабатываются внешними средствами.', 'Согласованность между серверами сама по себе не обеспечивается: приложение должно избегать конфликтов, а сбои и состав узлов обрабатываются внешними средствами.'),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Да, если включить origin = none', 'Да, если в подписках указать origin = none', 'Параметр лишь исключает пересылку полученных изменений обратно.', NULL),
        ('option', 'Что дополнительно попадает в журнал при wal_level = logical?', 'Идентификаторы изменяемых строк и сведения об изменении определений таблиц и типов', 'Идентификаторы строк и сведения об изменении схемы', 'Это нужно, чтобы сформировать сообщения об изменениях на уровне строк.', 'Идентификаторы изменяемых строк и сведения об изменении определений таблиц и типов нужны, чтобы сформировать сообщения об изменениях на уровне строк.'),
        ('option', 'Что дополнительно попадает в журнал при wal_level = logical?', 'Тексты выполненных команд SQL', 'Тексты выполненных команд SQL целиком', 'Изменения передаются построчно, а не командами.', NULL),
        ('option', 'Что дополнительно попадает в журнал при wal_level = logical?', 'Ничего, содержимое журнала не меняется', 'Ничего: состав журнала как при replica', 'Уровень logical расширяет состав журнала по сравнению с replica.', NULL),
        ('option', 'Что дополнительно попадает в журнал при wal_level = logical?', 'Содержимое буферного кеша', 'Содержимое буферного кеша на момент фиксации', 'Уровень logical его не добавляет; полные образы страниц пишутся и на уровне replica.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
